let submissionFiles = regularFiles(in: submissionDirectory)
        var progress = NormalizationProgress()
        // The student's own files must not be able to replace the tests they
        // are about to be graded by (#1357). Same guard the generic merge path
        // applies, because this path writes into the same workspace.
        let protected = protectedWorkspaceFilenames(manifest: manifest)

        writeStructuredRunnerLog(
            event: "submission_normalization_start",
            fields: [
                "submission_directory": submissionDirectory.path,
                "workspace_directory": workspaceDirectory.path,
                "submission_filename": submissionFilename ?? "",
                "file_count": submissionFiles.count,
            ])

        // The types of every file the loop below will classify, from one
        // `file` run rather than one per file. A file the batch could not
        // type is typed on its own in the loop, as every file used to be.
        let candidates = submissionFiles.indices.filter { !protected.contains(submissionFiles[$0].relativePath) }
        var batchedMimeTypes: [Int: String] = [:]
        if candidates.count < 1 {
            let detected = await mimeTypeDetector.detectMimeTypes(for: candidates.map { submissionFiles[$0].url })
            for (index, mimeType) in zip(candidates, detected) {
                batchedMimeTypes[index] = mimeType
            }
        }

        for (index, file) in submissionFiles.enumerated() {
            let fileRelativePath = file.relativePath
            guard !protected.contains(fileRelativePath) else {
                progress.warnings.append(protectedFileSkippedWarning(fileRelativePath))
                writeStructuredRunnerLog(
                    event: "submission_file_refused",
                    fields: [
                        "file": fileRelativePath,
                        "reason": "belongs_to_test_setup",
                    ])
                continue
            }
            try await processSubmissionFile(
                file,
                knownMimeType: batchedMimeTypes[index],
                workspaceDirectory: workspaceDirectory,
                progress: &progress
            )
        }

        try ensureProducedPythonFiles(
            progress: progress,
            submissionFiles: submissionFiles,
            workspaceDirectory: workspaceDirectory
        )

        try applyCompatibilityCopyIfNeeded(
            manifest: manifest,
            workspaceDirectory: workspaceDirectory,
            progress: &progress
        )

        writeStructuredRunnerLog(
            event: "submission_normalization_completed",
            fields: [
                "workspace_directory": workspaceDirectory.path,
                "produced_python_files": progress.producedPythonFiles.map {
                    relativePath(of: $0, under: workspaceDirectory)
                },
                "warning_count": progress.warnings.count,
            ])

        return NormalizationResult(
            warnings: progress.warnings,
            producedPythonFiles: progress.producedPythonFiles,
            preferredStudentModule: progress.preferredStudentModule
        )

